/**
 * Record integrity (ALCOA+ "original" / "accurate"): every assessment is
 * sealed with a SHA-256 over its canonical JSON at creation time and verified
 * on load, so silent corruption or manual edits are detectable.
 */

/** JSON with recursively sorted object keys; stable across engines. */
export function canonicalJson(value: unknown): string {
  if (value === null || typeof value !== 'object') {
    if (typeof value === 'number' && !Number.isFinite(value)) return 'null';
    return JSON.stringify(value) ?? 'null';
  }
  if (Array.isArray(value)) return `[${value.map(canonicalJson).join(',')}]`;
  const obj = value as Record<string, unknown>;
  const keys = Object.keys(obj)
    .filter((k) => obj[k] !== undefined)
    .sort();
  return `{${keys.map((k) => `${JSON.stringify(k)}:${canonicalJson(obj[k])}`).join(',')}}`;
}

export async function sha256Hex(data: string | ArrayBuffer | Uint8Array): Promise<string> {
  const bytes = typeof data === 'string' ? new TextEncoder().encode(data) : data;
  const digest = await crypto.subtle.digest('SHA-256', bytes as BufferSource);
  return Array.from(new Uint8Array(digest), (b) => b.toString(16).padStart(2, '0')).join('');
}

export async function seal<T extends object>(record: Omit<T, 'integrity'>): Promise<T> {
  const hash = await sha256Hex(canonicalJson(record));
  return { ...record, integrity: { algorithm: 'SHA-256', hash } } as T;
}

export async function verify<T extends { integrity: { hash: string } }>(record: T): Promise<boolean> {
  const { integrity, ...rest } = record;
  return (await sha256Hex(canonicalJson(rest))) === integrity.hash;
}
